/**
 * Hebrew language pack, node half. The empty apply gives the Loader a host-side row; the browser
 * half (lib/client.js, generated by build-client.mjs from dicts/he/*.json) ships through
 * `exports["./client"]`, exactly the shape of the shipped ui-brand-official plugin.
 */

/** The office's own language: what the interface opens in until somebody chooses otherwise. */
export const OFFICE_LOCALE = "he";

/** The harness's own language setting, registered by dsh-client-locale and written by its language row. */
export const LOCALE_NAMESPACE = "locale";

/**
 * Record the office's language as the workspace's language preference, once.
 *
 * WHERE THE DEFAULT ACTUALLY LIVES is the harness's own registration of this namespace, which the
 * image carries as `base: { preference: "he" }` (harness/customize.sh): adding a language is not
 * selecting one, and until DGO-550 nothing selected one, so the interface opened in whatever
 * `navigator.languages` asked for with the vendor's `en` as the fallback — measured 2026-10-13, the
 * owner's own phone showing «Into the Unknown», «Describe what you want to build…» and «Open sidebar»
 * while every one of those strings had a Hebrew value in the dictionaries this pack ships.
 *
 * This half exists for the one thing a composition default cannot do: turn a value nobody chose into
 * a PREFERENCE someone holds, so the office's language survives a future change of that default.
 * Two rules keep it a default and never an override:
 *   · it writes only while the setting holds NO preference — an explicit choice (Settings → General →
 *     שפה, the language row, which writes this same field) is never touched;
 *   · the pack's language and its 45 dictionaries are registered separately and unconditionally, so a
 *     settings service that is absent, not yet up, or holding a read-only document costs this line a
 *     log entry and nothing else.
 *
 * @param {object} ctx - host context; `settings` is optional, so this row cannot break a composition
 * that has none.
 */
export function recordOfficeLocale(ctx) {
	ctx.inject(["settings"], (settingsCtx) => {
		const problem = attempt(settingsCtx.settings);
		if (problem !== undefined) warn(problem);
	});
}

/**
 * One write attempt. `undefined` means the office's language is recorded, or the owner had already
 * chosen and nothing needed writing. The namespace is registered by ANOTHER plugin
 * (`dsh-client-locale`), so a composition whose order differs sees `undefined` from `get` and a
 * synchronous refusal from `update` — neither is a reason to give up the language pack, and the
 * image's composition default already answers the interface in Hebrew.
 *
 * @returns the failure, or undefined when the preference is stored (or being stored).
 */
function attempt(settings) {
	try {
		const stored = settings.get(LOCALE_NAMESPACE)?.preference;
		if (stored !== undefined && stored !== null && stored !== "") return undefined;
		settings.update(LOCALE_NAMESPACE, { preference: OFFICE_LOCALE }).then(
			() => console.log(`locale-he: the office's language (${OFFICE_LOCALE}) is now this workspace's preference`),
			(error) => warn(error),
		);
		return undefined;
	} catch (error) {
		return error;
	}
}

/** One warning, whatever goes wrong: the interface is not the language pack's to take down. */
function warn(error) {
	console.warn(`locale-he: could not record the office's language preference (${error?.message ?? error})`);
}

export function apply(ctx) {
	recordOfficeLocale(ctx);
}
